function readGitBlob(root, reference) {
  const type = run('git', ['-C', root, 'cat-file', '-t', reference]);
  if (type.status !== 0 || type.stdout.trim() !== 'blob') throw new Error(`preservation ref is not a readable blob: ${reference}`);
