  const pending = recovery.runLoggedTree(process.execPath, ['-e', treeScript(readyDir)], root, process.env, path.join(readyDir, 'run.log'), 120000, 200, {
    monotonicNow: clock.now(() => Number(process.hrtime.bigint()) / 1e6),
