  }
  ctx.verify = () => recovery.verifyRequireTargetDisposition(evidenceFile, ctx.dir, ctx.deps);
  ctx.readDisp = () => readJsonFile(ctx.dispFile);
  ctx.rewriteDisp = (mutate) => {
